import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import api from '../../utils/api';

export default function BoardMembersModal({ board, onClose, onUpdated }) {
  const [users, setUsers] = useState([]);
  const [members, setMembers] = useState(board.members || []);
  const [searchEmail, setSearchEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [adding, setAdding] = useState(false);

  // Fetch all users to search from
  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const { data } = await api.get('/users');
        setUsers(data.users);
      } catch {
        // Non-admin users can't fetch all users — that's OK
      }
    };
    fetchUsers();
  }, []);

  const handleAddMember = async (userId) => {
    setAdding(true);
    try {
      const { data } = await api.post(`/boards/${board._id}/members`, {
        userId,
        role: 'editor'
      });
      setMembers(data.board.members);
      toast.success('Member added!');
      onUpdated(data.board);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to add member');
    } finally {
      setAdding(false);
    }
  };

  const handleRemoveMember = async (userId) => {
    try {
      await api.delete(`/boards/${board._id}/members/${userId}`);
      setMembers(prev => prev.filter(m => m.user._id !== userId));
      toast.success('Member removed');
      onUpdated({ ...board, members: members.filter(m => m.user._id !== userId) });
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to remove member');
    }
  };

  // Filter users not already members and not the owner
  const memberIds = [
    board.owner._id,
    ...members.map(m => m.user?._id || m.user)
  ];

  const availableUsers = users.filter(u =>
    !memberIds.includes(u._id) &&
    u.email.toLowerCase().includes(searchEmail.toLowerCase())
  );

  const currentMembers = [
    { user: board.owner, role: 'owner' },
    ...members
  ];

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" style={{ maxWidth: 480 }} onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <h2>👥 Board Members</h2>
          <button className="btn btn-ghost btn-icon" onClick={onClose}>✕</button>
        </div>

        <div className="modal-body">

          {/* Current Members List */}
          <div style={{ marginBottom: 24 }}>
            <h4 style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 10, textTransform: 'uppercase', letterSpacing: '0.5px' }}>
              Current Members ({currentMembers.length})
            </h4>

            {currentMembers.map((m, i) => (
              <div key={m.user?._id || i} style={{
                display: 'flex', alignItems: 'center', gap: 10,
                padding: '10px 0',
                borderBottom: '1px solid var(--border)'
              }}>
                {/* Avatar */}
                <div style={{
                  width: 36, height: 36, borderRadius: '50%',
                  background: m.role === 'owner' ? '#f59e0b' : 'var(--primary)',
                  color: 'white', display: 'flex', alignItems: 'center',
                  justifyContent: 'center', fontSize: 14, fontWeight: 600,
                  flexShrink: 0
                }}>
                  {m.user?.name?.charAt(0).toUpperCase()}
                </div>

                {/* Name & Email */}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 14, fontWeight: 500 }}>{m.user?.name}</div>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{m.user?.email}</div>
                </div>

                {/* Role badge */}
                <span className={`badge ${m.role === 'owner' ? 'badge-review' : 'badge-in-progress'}`}>
                  {m.role}
                </span>

                {/* Remove button (not for owner) */}
                {m.role !== 'owner' && (
                  <button
                    className="btn btn-danger btn-sm"
                    onClick={() => handleRemoveMember(m.user._id)}
                    style={{ fontSize: 12, padding: '4px 10px' }}
                  >
                    Remove
                  </button>
                )}
              </div>
            ))}
          </div>

          {/* Add New Member Section */}
          <div>
            <h4 style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 10, textTransform: 'uppercase', letterSpacing: '0.5px' }}>
              Add Member
            </h4>

            <input
              className="form-control"
              placeholder="Search by email..."
              value={searchEmail}
              onChange={e => setSearchEmail(e.target.value)}
              style={{ marginBottom: 10 }}
            />

            {searchEmail && availableUsers.length === 0 && (
              <div style={{ textAlign: 'center', padding: '20px', color: 'var(--text-muted)', fontSize: 13 }}>
                No users found with that email
              </div>
            )}

            {availableUsers.slice(0, 5).map(u => (
              <div key={u._id} style={{
                display: 'flex', alignItems: 'center', gap: 10,
                padding: '8px 10px', borderRadius: 'var(--radius-sm)',
                border: '1px solid var(--border)', marginBottom: 8,
                background: 'var(--bg)'
              }}>
                <div style={{
                  width: 32, height: 32, borderRadius: '50%',
                  background: 'var(--primary)', color: 'white',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 13, fontWeight: 600, flexShrink: 0
                }}>
                  {u.name.charAt(0).toUpperCase()}
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 500 }}>{u.name}</div>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{u.email}</div>
                </div>
                <button
                  className="btn btn-primary btn-sm"
                  onClick={() => handleAddMember(u._id)}
                  disabled={adding}
                  style={{ fontSize: 12 }}
                >
                  + Add
                </button>
              </div>
            ))}

            {!searchEmail && (
              <p style={{ fontSize: 13, color: 'var(--text-muted)', textAlign: 'center', marginTop: 8 }}>
                Type an email above to search for users
              </p>
            )}
          </div>
        </div>

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}
